gVs(){return"\u0633\u06a9\u0627\u0646\u06d5\u0631\u06cc \u062a\u0627\u0642\u06cc\u06af\u06d5 \u067e\u06ce\u0648\u06cc\u0633\u062a\u06d5 \u0644\u06d5 \u06a9\u06d5\u06cc\u0633\u06cc \u0646\u0648\u06ce"},
gVt(){return"\u06a9\u06d5\u06cc\u0633 \u062f\u0631\u0648\u0633\u062a \u0646\u0627\u0628\u06ce\u062a \u062a\u0627 \u0633\u06a9\u0627\u0646\u06d5\u0631\u06ce\u06a9\u060c \u06cc\u0627\u0646 \xab\u062f\u06d5\u0631\u06d5\u06a9\u06cc\xbb \u0628\u06c6 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u06a9\u06d5 \u062a\u0627\u0642\u06cc\u06af\u06d5 \u0633\u06a9\u0627\u0646\u06cc \u0646\u06d5\u06a9\u0631\u062f\u0648\u0648\u06d5\u060c \u0647\u06d5\u06b5\u0646\u06d5\u0628\u0698\u06ce\u0631\u062f\u0631\u06ce\u062a."},
gVd(){return"\u062f\u062f\u0627\u0646\u06d5\u06a9\u0627\u0646 \u0628\u06d5 \u067e\u06cc\u062a\u06cc \u0686\u0627\u0631\u06d5\u06a9\u06d5\u06a9\u0627\u0646 \u0644\u06d5 \u0686\u0627\u067e\u062f\u0627 (UL1)"},
gVc(){return"\u0626\u06d5\u06af\u06d5\u0631 \u06a9\u0627\u0631\u0627 \u0628\u06ce\u062a: \u0644\u06d5\u06cc\u0628\u06b5\u06cc \u06a9\u06d5\u06cc\u0633 \u0648 \u067e\u0633\u0648\u0648\u0644\u06d5\u06cc \u0648\u06d5\u0631\u06af\u0631\u062a\u0646 \u062f\u062f\u0627\u0646\u06d5\u06a9\u0627\u0646 \u0628\u06d5 UL1\u060c UR2\u2026 \u062f\u06d5\u0646\u0648\u0648\u0633\u0646 \u0646\u06d5\u06a9 \u0698\u0645\u0627\u0631\u06d5\u06cc FDI (21\u060c 12\u2026)."},
gU2(){return"\u0644\u06d5\u06cc\u0628\u06b5\u06cc \u0628\u0686\u0648\u0648\u06a9\u06cc \u06a9\u06d5\u06cc\u0633 (A6\u060c 4 \u0644\u06d5 \u067e\u06d5\u0695\u06d5\u06cc\u06d5\u06a9\u06cc A4)"},
gU1(){return"\u0626\u06d5\u06af\u06d5\u0631 \u06a9\u0627\u0631\u0627 \u0628\u06ce\u062a: \u0644\u06d5\u06cc\u0628\u06b5\u06cc \u06a9\u06d5\u06cc\u0633 \u062f\u06d5\u0628\u06ce\u062a\u06d5 \u0686\u0627\u0631\u06d5\u06a9\u06cc A4 \u0628\u06d5 \u0647\u06d5\u0645\u0627\u0646 \u0642\u06d5\u0628\u0627\u0631\u06d5\u06cc \u0646\u0648\u0648\u0633\u06cc\u0646\u060c \u0626\u06d5\u06af\u06d5\u0631 4 \u0644\u06d5 \u067e\u06d5\u0695\u06d5\u06cc\u06d5\u06a9\u062f\u0627 \u0686\u0627\u067e \u0628\u06a9\u06d5\u06cc\u062a \u0646\u0648\u0648\u0633\u06cc\u0646\u06d5\u06a9\u06d5 \u0628\u06d5 \u0642\u06d5\u0628\u0627\u0631\u06d5\u06cc \u062a\u06d5\u0648\u0627\u0648 \u062f\u06d5\u0631\u062f\u06d5\u0686\u06ce\u062a \u0646\u06d5\u06a9 \u0628\u0686\u0648\u0648\u06a9\u06a9\u0631\u0627\u0648\u06d5. \u0628\u06c6 \u0686\u0627\u067e\u06a9\u06d5\u0631\u06cc \u0644\u06d5\u06cc\u0628\u06b5\u06cc 4\xd76 \u0626\u06cc\u0646\u062c \u06cc\u0634 \u06af\u0648\u0646\u062c\u0627\u0648\u06d5."},
ga30(){return"\u06af\u06c6\u0695\u06cc\u0646\u06cc \u062a\u06d5\u06a9\u0646\u06cc\u0634\u06cc\u0627\u0646\u06cc \u0633\u06a9\u06d5\u0646\u06d5\u0631"},
gab8(){return"\u0632\u06c6\u0631\u062a\u0631\u06cc\u0646 \u06cc\u06d5\u06a9\u06d5 \u0628\u06c6 \u0647\u06d5\u0631 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 (\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5)"},
gab7(){return"\u062a\u06d5\u0646\u0647\u0627 \u0626\u06d5\u0645 \u0698\u0645\u0627\u0631\u06d5\u06cc\u06d5 \u0644\u06d5 \u06cc\u06d5\u06a9\u06d5 \u0628\u06c6 \u0647\u06d5\u0631 \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9 \u062f\u06d5\u0698\u0645\u06ce\u0631\u062f\u0631\u06ce\u062a\u060c \u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 5. \u0628\u06d5\u062a\u0627\u06b5\u06cc \u0628\u0647\u06ce\u06b5\u06d5 \u0628\u06c6 \u0628\u06ce \u0633\u0646\u0648\u0648\u0631."},
gabL(){return"\u0646\u0631\u062e\u06cc \u0628\u06d5\u0631\u0632\u062a\u0631 \u062f\u0648\u0627\u06cc (\u06cc\u06d5\u06a9\u06d5 / \u0645\u0627\u0646\u06af)"},
gabN(){return"\u0646\u0631\u062e\u06cc \u0628\u06d5\u0631\u0632\u062a\u0631 \u0628\u06c6 \u0647\u06d5\u0631 \u06cc\u06d5\u06a9\u06d5\u06cc\u06d5\u06a9"},
gabM(){return"\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5. \u0626\u06d5\u0648 \u06cc\u06d5\u06a9\u0627\u0646\u06d5\u06cc \u0644\u06d5 \u0645\u0627\u0646\u06af\u06ce\u06a9\u062f\u0627 \u0644\u06d5\u0645 \u0698\u0645\u0627\u0631\u06d5\u06cc\u06d5 \u0632\u06cc\u0627\u062a\u0631 \u062f\u06d5\u0628\u0646 (\u0628\u06d5 \u0695\u06cc\u0632\u0628\u06d5\u0646\u062f\u06cc \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646) \u0628\u06d5 \u0646\u0631\u062e\u06cc \u0628\u06d5\u0631\u0632\u062a\u0631 \u062f\u06d5\u0698\u0645\u06ce\u0631\u062f\u0631\u06ce\u0646\u060c \u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 600 \u06cc\u06d5\u06a9\u06d5\u06cc \u06cc\u06d5\u06a9\u06d5\u0645 \u0628\u06d5 \u0646\u0631\u062e\u06cc \u0626\u0627\u0633\u0627\u06cc\u06cc\u060c \u067e\u0627\u0634\u0627\u0646 1,500 \u0628\u06c6 \u0647\u06d5\u0631 \u06cc\u06d5\u06a9\u06d5\u06cc\u06d5\u06a9. \u06a9\u0627\u0631\u06cc\u06af\u06d5\u0631\u06cc \u0644\u06d5\u0633\u06d5\u0631 \u0646\u0631\u062e\u06cc \u062a\u0627\u06cc\u0628\u06d5\u062a\u06cc \u06a9\u06d5\u0631\u06d5\u0633\u062a\u06d5\u06a9\u0627\u0646 \u0646\u06cc\u06cc\u06d5. \u0628\u06d5\u062a\u0627\u06b5\u06cc \u0628\u0647\u06ce\u06b5\u06d5 \u0628\u06c6 \u0647\u06cc\u0686."},
gabe(){return"\u0695\u06c6\u0698\u06cc \u0645\u0648\u0648\u0686\u06d5 (\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5\u060c 1-28)"},
gabd(){return"\u06a9\u06c6\u0645\u06cc\u0634\u0646 \u0644\u06d5\u0633\u06d5\u0631 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646\u06cc \u0626\u06d5\u0645 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5 \u0644\u06d5 \u0695\u06c6\u0698\u06cc \u062f\u0648\u0627\u06cc \u0626\u06d5\u0645 \u0695\u06c6\u0698\u06d5\u0648\u06d5 \u062a\u0627 \u0647\u06d5\u0645\u0627\u0646 \u0695\u06c6\u0698\u06cc \u0645\u0627\u0646\u06af\u06cc \u062f\u0627\u0647\u0627\u062a\u0648\u0648 \u062f\u06d5\u0698\u0645\u06ce\u0631\u062f\u0631\u06ce\u062a (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 4 = \u0644\u06d5 5\u0640\u06d5\u0648\u06d5 \u062a\u0627 4). \u0628\u06d5\u062a\u0627\u06b5\u06cc \u0628\u0647\u06ce\u06b5\u06d5 \u0628\u06c6 \u0645\u0627\u0646\u06af\u06cc \u0632\u0627\u06cc\u06cc\u0646\u06cc."},
gUg(){return"\u06a9\u06c6\u0645\u06cc\u0634\u0646"},
gUf(){return"\u0647\u06cc\u0686 \u06a9\u06c6\u0645\u06cc\u0634\u0646\u06ce\u06a9 \u0628\u06c6 \u06a9\u06d5\u06cc\u0633\u06d5 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5\u06a9\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646 \u0646\u06cc\u06cc\u06d5"},
gUe(){return"\u06a9\u06d5\u06cc\u0633\u06d5 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5\u06a9\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646 \u0644\u06d5 \u06a9\u06c6\u0645\u06cc\u0634\u0646\u06cc \u0647\u06cc\u0686 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06ce\u06a9 \u0646\u0627\u0698\u0645\u06ce\u0631\u062f\u0631\u06ce\u0646. \u0644\u06d5\u0633\u06d5\u0631 \u0626\u06d5\u0648 \u0645\u0627\u0646\u06af\u0627\u0646\u06d5\u06cc \u0645\u0648\u0648\u0686\u06d5 \u062c\u06ce\u0628\u06d5\u062c\u06ce \u062f\u06d5\u0628\u06ce\u062a \u06a9\u06d5 \u0644\u06d5 \u0626\u06ce\u0633\u062a\u0627\u0648\u06d5 \u062f\u0631\u0648\u0633\u062a \u062f\u06d5\u06a9\u0631\u06ce\u0646."},
